    }
    db.get('SELECT * FROM usuarios WHERE id = ?', [usuarioId], (err, usuario) => {
      if (err || !usuario) {
        return res.status(401).json({ erro: 'USUARIO_DESCONHECIDO', mensagem: 'Usuário desconhecido' });
      }

      const atividadeId = req.params.id;

      // 1. Verificar se atividade existe
      db.get('SELECT * FROM atividades WHERE id = ?', [atividadeId], (err, atividade) => {
        if (err || !atividade) {
          return res.status(404).json({ erro: 'NAO_ENCONTRADO', mensagem: 'Atividade não encontrada' });
        }

        // 2. Verificar se atividade cancelada
        if (atividade.situacao === 'cancelada') {
          return res.status(422).json({ erro: 'ATIVIDADE_CANCELADA', mensagem: 'Atividade cancelada' });
        }

        // 3. Verificar se usuário é participante com inscrição confirmada
        db.get('SELECT * FROM inscricoes WHERE atividadeId = ? AND participanteId = ? AND status = ?',
          [atividadeId, usuarioId, 'confirmada'], (err, inscricao) => {
            if (err || !inscricao) {
              return res.status(403).json({ erro: 'NAO_INSCRITO', mensagem: 'Participante não inscrito' });
            }

            // 4. Verificar se atividade encerrada (fim do último encontro)
            db.all('SELECT * FROM encontros WHERE atividadeId = ? ORDER BY inicio ASC', [atividadeId], (err, encontros) => {
              if (err || !encontros || encontros.length === 0) {
                return res.status(422).json({ erro: 'ATIVIDADE_NAO_ENCERRADA', mensagem: 'Atividade ainda não encerrada' });
              }

              const ultimoEncontro = encontros[encontros.length - 1];
              const agora = new Date(currentClock);
              const fimEncontro = new Date(ultimoEncontro.fim);

              if (agora < fimEncontro) {
                return res.status(422).json({ erro: 'ATIVIDADE_NAO_ENCERRADA', mensagem: 'Atividade ainda não encerrada' });
              }

              // 5. Verificar frequência mínima (presencas * 4 >= encontros * 3)
              const encontroIds = encontros.map(e => e.id);
              db.all('SELECT * FROM presencas WHERE participanteId = ? AND encontroId IN (?',
                [usuarioId, encontroIds], (err, presencas) => {
                  const presencasCount = presencas.length;
                  const encontrosCount = encontros.length;

                  if (presencasCount * 4 < encontrosCount * 3) {
                    return res.status(422).json({ erro: 'PRESENCA_INSUFICIENTE', mensagem: 'Presença insuficiente' });
                  }

                  // 6. Calcular carga horária total (soma integral dos minutos dos encontros)
                  let cargaHorariaMinutos = 0;
                  for (const enc of encontros) {
                    const inicioMs = new Date(enc.inicio).getTime();
                    const fimMs = new Date(enc.fim).getTime();
                    cargaHorariaMinutos += Math.max(0, Math.floor((fimMs - inicioMs) / 60000));
                  }

                  // 7. Verificar se certificado já existe
                  db.get('SELECT * FROM certificados WHERE atividadeId = ? AND participanteId = ?',
                    [atividadeId, usuarioId], (err, certificadoExistente) => {
                      if (certificadoExistente) {
                        return res.status(200).json(certificadoExistente);
                      }

                      // 8. Gerar código do certificado SA26-XXXX-XXXX
                      const alfabeto = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
                      let codigo = 'SA26-';
                      for (let i = 0; i < 4; i++) {
                        codigo += alfabeto[Math.floor(Math.random() * alfabeto.length)];
                      }
                      codigo += '-';
                      for (let i = 0; i < 4; i++) {
                        codigo += alfabeto[Math.floor(Math.random() * alfabeto.length)];
                      }

                      // 9. Salvar certificado no banco
                      const emitidoEm = currentClock;
                      db.run('INSERT INTO certificados (codigo, atividadeId, participanteId, cargaHorariaMinutos, presencas, encontros, emitidoEm) VALUES (?, ?, ?, ?, ?, ?, ?)',
                        [codigo, atividadeId, usuarioId, cargaHorariaMinutos, presencasCount, encontrosCount, emitidoEm], (err) => {
                          if (err) {
                            return res.status(500).json({ erro: 'ERRO_INTERNO', mensagem: err.message });
                          }

                          const certificado = {
                            codigo,
                            atividadeId,
                            participanteId: usuarioId,
                            cargaHorariaMinutos,
                            presencas: presencasCount,
                            encontros: encontrosCount,
                            emitidoEm
