import { criarServidor } from '../api/servidor.js';

const servidor = await criarServador({ porta: 0 });
try {
  const porta = servidor.porta;

  // Helper para POST com X-Usuario
  const postCertificado = async (id, usuarioId) => {
    return await fetch(`http://localhost:${porta}/atividades/${id}/certificado`, {
      method: 'POST',
      headers: { 'x-usuario': usuarioId }
    });
  };

  // Helper para reset
  const reset = async () => {
    await fetch(`http://localhost:${porta}/_teste/reset`, { method: 'POST' });
  };

  // Helper para avançar relógio
  const avancarRelogio = async (iso) => {
    await fetch(`http://localhost:${porta}/_teste/relogio`, {
      method: 'PUT',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ agora: iso })
    });
  };

  // Cenário 1: inexistente -> 404 + NAO_ENCONTRADO
  {
    await reset();
    const res = await postCertificado('atv_inexistente', 'p-carla');
    const data = await res.json();
    if (res.status !== 404 || data.erro !== 'NAO_ENCONTRADO') {
      console.error('FALHA: inexistente', res.status, data);
      process.exit(1);
    }
    console.log('PASS: inexistente -> 404 + NAO_ENCONTRADO');
  }

  // Cenário 2: não inscrito -> 403 + NAO_INSCRITO
  {
    await reset();
    const res = await postCertificado('atv_1a2b3c4d', 'p-diego');
    const data = await res.json();
    if (res.status !== 403 || data.erro !== 'NAO_INSCRITO') {
      console.error('FALHA: nao inscrito', res.status, data);
      process.exit(1);
    }
    console.log('PASS: nao inscrito -> 403 + NAO_INSCRITO');
  }

  // Cenário 3: atividade nao encerrada -> 422 + ATIVIDADE_NAO_ENCERRADA
  {
    await reset();
    const res = await postCertificado('atv_1a2b3c4d', 'p-carla');
    const data = await res.json();
    if (res.status !== 422 || data.erro !== 'ATIVIDADE_NAO_ENCERRADA') {
      console.error('FALHA: nao encerrada', res.status, data);
      process.exit(1);
    }
    console.log('PASS: atividade nao encerrada -> 422 + ATIVIDADE_NAO_ENCERRADA');
  }

  // Cenário 4: presenca insuficiente -> 422 + PRESENCA_INSUFICIENTE
  {
    await reset();
    // Avançar relógio para depois do fim do encontro
    await avancarRelogio('2026-10-20T23:00:00-03:00');
    const res = await postCertificado('atv_1a2b3c4d', 'p-carla');
    const data = await res.json();
    if (res.status !== 422 || data.erro !== 'PRESENCA_INSUFICIENTE') {
      console.error('FALHA: presenca insuficiente', res.status, data);
      process.exit(1);
    }
    console.log('PASS: presenca insuficiente -> 422 + PRESENCA_INSUFICIENTE');
  }
} finally {
  await servidor.fechar();
}

